fn fibonacci(n: usize) -> Vec<i32> {
    // Pre-allocate the vector with the right size for performance
    let mut fib = Vec::with_capacity(n);

    // According to problem, n >= 2, so safe to initialize first two elements
    fib.push(0);
    fib.push(1);

    // Compute Fibonacci numbers from index 2 to n-1
    for i in 2..n {
        let next = fib[i - 1] + fib[i - 2];
        fib.push(next);
    }

    fib
}